#include "foundation_adapter.h"
#include <assert.h>
#include <math.h>
#include <stdio.h>
#include <string.h>
int main(void)
{
    float out[256], left[256], right[256];
    wobble_t a, direct, prepared;
    synth_slot_t slot;
    assert(synth_init(&slot, wobble_foundation_binding(&a)));
    assert(a.sample_rate == 44100);
    synth_param_key_t key = {WOBBLE_EXPERIMENT_ENGINE, WOBBLE_EXPERIMENT_SCHEMA, W_STEREO};
    assert(synth_set(&slot,key,89));
    synth_param_key_t bad = synth303_key(W_CUTOFF);
    float cutoff=a.p[W_CUTOFF];
    assert(!synth_set(&slot,bad,0) && a.p[W_CUTOFF]==cutoff);
    bad=key;bad.schema=2;assert(!synth_set(&slot,bad,0));
    bad=key;bad.param=16;assert(!synth_set(&slot,bad,0));
    synth_note(&slot,48,1,1,80);
    direct=a;
    for(int n=1;n<=256;++n) {
        synth_render(&slot,out,n);
        wobble_render(&direct,left,right,(size_t)n);
        for(int i=0;i<n;++i) {
            assert(isfinite(out[i]));
            assert(out[i]==.5f*(left[i]+right[i]));
        }
    }
    synth_off(&slot);
    for(int n=0;n<8;++n)synth_render(&slot,out,256);
    assert(synth_idle(&slot));
    for(int i=0;i<256;++i)assert(out[i]==0);
    wobble_init(&prepared,44100);
    wobble_set(&prepared,W_CRUSH,.3f);
    synth_note(&slot,55,0,0,100);
    uint8_t ticket;
    assert(synth_request(&slot,wobble_foundation_binding(&prepared),&ticket));
    assert(!synth_request(&slot,wobble_foundation_binding(&a),0));
    assert(synth_boundary(&slot));
    assert(slot.acknowledged==ticket && !a.active && !prepared.active);
    assert(prepared.p[W_CRUSH]==.3f);
    synth_note(&slot,48,0,0,80);
    assert(synth_active(&slot));
    synth_transport(&slot,0);
    assert(synth_idle(&slot) && prepared.p[W_CRUSH]==.3f);
    printf("PASS PR212 exact interface:44100Hz, fragments1..256, mono downmix, identity/schema, boundary ACK, panic/settings; state=%zu scratch=%zu\n",sizeof(a),sizeof(right));
    return 0;
}

/* SPDX-License-Identifier: GPL-3.0-only */
/* X0X send FX and master, shared by the drum and bass parts. A port of 9W9's
 * (GPL-3.0) send reverb, tempo-synced delay and master stage:
 *
 *   out = volume * glue( dist( dry + reverb(rev) + delay(dly) ) )
 *
 *  - Reverb: four combs + two allpasses, the comb loop quantised to 12 bits
 *    (the early-rack grain), damping in the loop, HPF on the send.
 *  - Delay: a note division of the tempo, slewed so time changes warp instead of
 *    clicking, feedback through a darkening one-pole, 12-bit write, HPF on the
 *    send. TYPE = DIGI is 9W9's delay exactly. TYPE = TAPE (an X0X addition, for
 *    the 303) reads the same line with wow and flutter, saturates inside the
 *    loop, darkens the loop further and lets feedback run slightly past unity
 *    into self-oscillation that the saturation holds; WEAR scales all of it.
 *  - Master: 9W9's seven distortion characters (or Off) and its one-knob glue
 *    compressor (hard bypass at 0), then volume.
 *
 * The delay line is int16 (9W9 writes it at 12 bits, so nothing is lost; values
 * past +-16 full scale saturate) and is passed in by the caller (.pool). The
 * reverb lines are int16 combs (also 12-bit in 9W9) and float allpasses, inside
 * the struct. Both effects go idle (no per-sample work) once their input and
 * their lines are silent. */
#pragma once
#include <stdint.h>
#include "x0x_param.h"
#include "drum909_dsp.h"

#define FX_RV_COMB_TOTAL (1116 + 1188 + 1277 + 1356)
#define FX_RV_AP_TOTAL (556 + 441)
#define FX_RV_APR_TOTAL (579 + 457)   /* X0X: the right side's allpasses */

enum { FX_VOLUME, FX_DIST, FX_DRIVE, FX_COMP,
       FX_RV_DECAY, FX_RV_TONE, FX_RV_HPF, FX_RV_LEVEL,
       FX_DL_TIME, FX_DL_FDBK, FX_DL_TONE, FX_DL_LEVEL,
       FX_DL_HPF, FX_DL_TYPE, FX_DL_WEAR, FX_DL_PING, FX_NPARAMS };

struct fxbus {
    /* reverb */
    float rv_decay, rv_tone, rv_level;
    d9_biquad_t rv_hp;
    int16_t comb[FX_RV_COMB_TOTAL];
    volatile uint8_t muted;          /* uses alignment padding: reverb/delay/master output gates, not pots */
    uint8_t dl_signal;              /* existing padding: input/wet activity in last block */
    float ap[FX_RV_AP_TOTAL];
    int32_t cpos[4], apos[2];
    float cdmp[4];
    int32_t rv_quiet;
    float apr[FX_RV_APR_TOTAL];       /* X0X stereo: the right side reads the combs with alternating
                                       * signs through its own allpasses (the left is 9W9's) */
    int32_t aposr[2];
    /* delay */
    float dl_time_ms, dl_fdbk, dl_tone, dl_level, bpm, wear;
    int32_t dl_div, dl_type;
    d9_biquad_t dl_hp;
    int16_t *dbuf;
    int32_t dlen, w, dl_quiet;
    float dcur, lp, tape_hp;
    uint32_t wow_ph, flut_ph;
    int32_t dl_ping;                  /* X0X: ping-pong, a second tap at twice the time */
    /* master */
    float drive, volume, comp;
    int32_t dist_mode;
    d9_shape_t shape;
    float crush_st[2], crush_str[2];
    float comp_env_db, comp_det, c_thr, c_slope, c_makeup, c_drel, c_atk, c_rel;
    uint8_t pots[FX_NPARAMS];
};
typedef struct fxbus fxbus_t;

void fxbus_init(fxbus_t *f, int16_t *dly_buf, int dly_len);
void fxbus_set_bpm(fxbus_t *f, float bpm);
void fxbus_process(fxbus_t *f, const float *dry, const float *rev, const float *dly, float *out, int n);
/* X0X stereo: dry in L / R, the sends mono; with everything centred and no reverb, out_l and out_r
 * are fxbus_process's out exactly */
void fxbus_process_st(fxbus_t *f, const float *dry_l, const float *dry_r, const float *rev, const float *dly,
                      float *out_l, float *out_r, int n);
int fxbus_nparams(void);
const x0x_param_t *fxbus_param(int i);
void fxbus_set(fxbus_t *f, int i, int value);
int fxbus_get(const fxbus_t *f, int i);

// SPDX-License-Identifier: GPL-3.0-only
// EC-20261026-009: the browser must reject corrupted OTA identity frames.
// Firmware ota_send_msg(0x11) declares body length 27 and appends ~sum(body).
// Test-only; the installer/OTA specialist owns the implementation repair.
import test from 'node:test';
import assert from 'node:assert/strict';
import { Updater, pack7 } from '../web/fm1ota.js';

function identityFrame(text = 'SMK-37 Pro_900') {
  const name = Array.from(new TextEncoder().encode(text));
  assert.ok(name.length <= 27);
  const payload = Array.from({ length: 27 }, (_, i) => name[i] || 0);
  return [0, 0x59, 0x11, 27, 0, 0, ...payload,
    (~payload.reduce((sum, byte) => sum + byte, 0)) & 0xff];
}

async function discover(raw) {
  const input = {
    name: 'SMK-37 Pro MIDI', state: 'connected', onmidimessage: null,
    async open() {},
  };
  const output = {
    name: input.name, state: 'connected', async open() {},
    send() {
      if (input.onmidimessage) input.onmidimessage({
        data: new Uint8Array([0xf0, ...pack7(raw), 0xf7]),
      });
    },
  };
  const updater = new Updater({
    inputs: new Map([['in', input]]),
    outputs: new Map([['out', output]]),
  });
  const dev = await updater.find();
  if (dev) dev.link.close();
  return dev ? dev.id.text : null;
}

test('positive: checksummed identity frame discovers the correct model and version', async () => {
  assert.equal(await discover(identityFrame()), 'SMK-37 Pro_900');
});

test('negative: corrupt identity checksum must not bind a keyboard', async () => {
  const frame = identityFrame();
  frame[33] ^= 1;
  assert.equal(await discover(frame), null,
    'FAIL_BEFORE_FIX: OTA identity with corrupt checksum was trusted');
});

test('negative: corrupted version byte with unchanged checksum must not bind', async () => {
  const frame = identityFrame();
  frame[6 + 'SMK-37 Pro_90'.length] = '1'.charCodeAt(0);
  assert.equal(await discover(frame), null,
    'FAIL_BEFORE_FIX: corrupted product identity was accepted');
});

test('negative: contradictory identity length header must not bind', async () => {
  const frame = identityFrame();
  frame[3] = 26;
  assert.equal(await discover(frame), null,
    'FAIL_BEFORE_FIX: identity frame declared 26 bytes but carried 27');
});
